window.gsap={from:(e,o={})=>{const n=e instanceof Element?e:null;if(!n)return;n.style.transition=`opacity ${o.duration||.3}s ease, transform ${o.duration||.3}s ease`;n.style.opacity="0";n.style.transform=`translateY(${o.y||0}px)`;requestAnimationFrame(()=>{n.style.opacity="1";n.style.transform="translateY(0)"})},to:(e,o={})=>{const n=e instanceof Element?e:null;if(!n)return;Object.assign(n.style,o)}};
